const EmbeddedApps = {};

EmbeddedApps.parse = (embeddedApps) => {
  const slidoApp = EmbeddedApps.parseSlido(embeddedApps);
  const parsed = {
    slidoApp: {
      appId: slidoApp.appId,
      instanceInfo: slidoApp.instanceInfo,
      state: slidoApp.state
    }
  };

  return parsed;
};

EmbeddedApps.parseSlido = (embeddedApps) => {
  const slidoApp = embeddedApps.find((embeddedApp) => embeddedApp.appId = 'Y2lzY29zcGFyazovL3VzL0FQUExJQ0FUSU9OLzQxODc1MGQ0LTM3ZDctNGY2MC1hOWE3LWEwZTE1NDFhNjRkNg');

  return slidoApp;
};

EmbeddedApps.getEmbeddedApps = (oldEmbeddedApps, newEmbeddedApps) => {
  let previous = null;

  if (oldEmbeddedApps) {
    previous = oldEmbeddedApps;
  }
  const current = newEmbeddedApps && EmbeddedApps.parse(newEmbeddedApps);
  const updates = {};

  if (current) {
    if (previous && previous.slidoApp?.state !== 'RUNNING' && current.slidoApp?.state === 'RUNNING' || !previous && current.slidoApp?.state === 'RUNNING') {
      updates.slidoChanged = true;
    }

    if (previous && previous.slidoApp?.state === 'RUNNING' && current.slidoApp?.state !== 'RUNNING') {
      updates.slidoChanged = true;
    }
  }

  return {
    previous,
    current,
    updates
  };
};

export default EmbeddedApps;
